import "server-only";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { env } from "./env";

/**
 * Where uploaded files live. Local disk now; an S3-compatible provider can
 * implement the same interface later without touching callers.
 */
export interface StorageProvider {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by the server only; this rejects anything path-like anyway. */
const KEY = /^[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+\.(png|jpg)$/;

/**
 * Starter artworks are added to the database by a migration, which cannot write files. Their files ship in the repo
 * (assets/artworks/<name>.png or .jpg) and are served from there when the storage folder has no copy (key artworks/seed-<name>.<ext>).
 */
const BUNDLED_KEY = /^artworks\/seed-([a-z0-9-]+)\.(png|jpg)$/;
const BUNDLED_DIR = path.resolve(/* turbopackIgnore: true */ process.cwd(), "../../assets/artworks");

class LocalDiskStorage implements StorageProvider {
  constructor(private readonly root: string) {}

  private file(key: string): string {
    if (!KEY.test(key)) throw new Error("Invalid storage key.");
    return path.join(this.root, key);
  }

  async put(key: string, bytes: Uint8Array) {
    const f = this.file(key);
    await mkdir(path.dirname(f), { recursive: true });
    await writeFile(f, bytes, { flag: "wx" }); // never overwrite
  }

  async get(key: string) {
    try {
      return await readFile(this.file(key));
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== "ENOENT") throw e;
      const bundled = BUNDLED_KEY.exec(key);
      if (!bundled) return null;
      return readFile(path.join(BUNDLED_DIR, `${bundled[1]}.${bundled[2]}`)).catch(() => null);
    }
  }

  async delete(key: string) {
    await rm(this.file(key), { force: true });
  }
}

export const storage: StorageProvider = new LocalDiskStorage(path.resolve(env.STORAGE_DIR ?? path.join(/* turbopackIgnore: true */ process.cwd(), "storage")));
